mapper.select:
select
    id
from b_xiecheng_colliding_data_contrast
where is_delete = 1
     and update_time < #{startTime}
order by update_time asc limit #{size};

mapper.delete:
delete from b_xiecheng_colliding_data_contrast
where id in

    #{id}

mapper.select:
select a.*  from  ${tableName} a left join b_xiecheng_colliding_data_contrast b
                 on a.cell  = b.cell_sha256_code_list and b.is_delete = 0 where ${filterScore}
                                                                             and b.id is null
limit #{xieChengCleanLimitCount}

select cell ,rn   from (
                           select cell ,row_number() over(partition by cell ) as rn from ${tableName}
                       ) a  where a.rn >1

select a.id  from  b_xiecheng_colliding_data_loop_cycle a left join b_xiecheng_colliding_data_contrast b
            on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0 and b.local_id is null
           where   b.id is null and a.is_delete =0    limit #{xieChengCleanCount}

select  a.id from  b_xiecheng_colliding_data_rob a  join b_xiecheng_colliding_data_loop_cycle b
                                                                  on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
where a.is_delete =0 limit #{xieChengCleanCount}

select a.id from  b_xiecheng_colliding_data_contrast a   join b_xiecheng_colliding_data_rob b
                                                                  on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
where a.is_delete =0 limit #{xieChengCleanCount}

select a.* from  b_xiecheng_colliding_data_contrast a left   join b_xiecheng_colliding_data_rob b
                                                                on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
where a.is_delete =0 and b.id is null limit #{xieChengCleanCount}
